mapper.select:
with query as ( select plainto_tsquery(cast(#{tsConfig} as regconfig), #{question}) as tsq ) select unit.source_id, unit.terminal_unit_identity as item_key, unit.terminal_unit_identity as concept_id, concat_ws(' / ', nullif(fc.title, ''), nullif(unit.key_path, '')) as title, trim(concat_ws(E'\n', unit.display_text, unit.field_description, unit.field_aliases_json::text)) as content, ( unit.metadata_json || jsonb_build_object( 'terminalUnitId', unit.id, 'unitId', unit.unit_id, 'terminalUnitIdentity', unit.terminal_unit_identity, 'factCardId', unit.fact_card_id, 'cardId', unit.card_id, 'keyPath', unit.key_path, 'parentPath', unit.parent_path, 'terminalKey', unit.terminal_key, 'value', unit.value_text, 'valueType', unit.value_type, 'displayText', unit.display_text, 'channel', 'fact_card_terminal_fts' ) )::text as metadata_json, unit.review_status, array_remove(array[sf.file_path], null)::text[] as source_paths, null::integer as chunk_index, false as verbatim, ts_rank_cd(unit.search_tsv, query.tsq)
+ case when lower(unit.field_label) like #{likeToken} then 4.0 else 0 end + case when lower(unit.field_aliases_json::text) like #{likeToken} then 3.0 else 0 end + case when lower(unit.key_path) like #{likeToken} then 5.0 else 0 end + case when lower(unit.parent_path) like #{likeToken} then 2.0 else 0 end + case when lower(unit.terminal_key) like #{likeToken} then 4.0 else 0 end + case when lower(unit.display_text) like #{likeToken} then 5.0 else 0 end + case when lower(unit.value_text) like #{likeToken} then 3.0 else 0 end + case when lower(unit.normalized_value) like #{likeToken} then 3.0 else 0 end + case when lower(unit.value_type) like #{likeToken} then 1.0 else 0 end + case when lower(unit.fts_text) like #{likeToken} then 2.0 else 0 end
as score from fact_card_terminal_units unit join fact_cards fc on fc.id = unit.fact_card_id left join source_files sf on sf.id = unit.source_file_id cross join query where unit.search_tsv @@ query.tsq
or lower(unit.field_label) like #{likeToken} or lower(unit.field_aliases_json::text) like #{likeToken} or lower(unit.key_path) like #{likeToken} or lower(unit.parent_path) like #{likeToken} or lower(unit.terminal_key) like #{likeToken} or lower(unit.display_text) like #{likeToken} or lower(unit.value_text) like #{likeToken} or lower(unit.normalized_value) like #{likeToken} or lower(unit.value_type) like #{likeToken} or lower(unit.fts_text) like #{likeToken}
order by score desc, unit.updated_at desc, unit.terminal_unit_identity asc limit #{limit}
